<script module lang="ts">
/**
 * Switches between peer views of one subject (`design/components/tabs.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tabs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext, type Snippet } from 'svelte'

import * as zag from '@zag-js/tabs'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  agentMember,
  attributes,
  joinSlot,
  normalizeProps,
  revealInline,
  useDirection,
  watchEffect,
  type IconRole,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/overlays/tabs.module.css'
import Badge from '../structure/Badge.svelte'

export type TabsOrientation = NonNullable<TabsProps['orientation']>

export interface TabDescriptor {
  value: string
  label: string
  icon?: IconRole
  count?: number
  disabled?: boolean
}

export interface TabsProps {
  /**
   * One `Tabs.Content` per tab.
   */
  children: Snippet
  defaultValue?: string
  /**
   * Keeps inactive panels mounted and `hidden` (Radix `forceMount`), so a form being edited or
   * an embedded player survives a tab switch. The default unmounts them, so the common case does
   * not pay to mount everything.
   */
  keepMounted?: boolean
  onChange?: (value: string) => void
  /**
   * Vertical is the same component on its side, with the rule down the start edge instead of
   * along the bottom. Use it when labels are long enough that a horizontal strip would wrap,
   * because wrapped tabs no longer read as peers.
   */
  orientation?: 'horizontal' | 'vertical'
  tabs: TabDescriptor[]
  value?: string
}
</script>

<script lang="ts">
let {
  children,
  defaultValue,
  keepMounted = false,
  onChange,
  orientation = 'horizontal',
  tabs,
  value,
}: TabsProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
let list = $state<HTMLElement | null>(null)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      value: value,
      defaultValue: defaultValue ?? tabs[0]?.value,
      orientation: orientation,
      onValueChange: (details) => {
        onChange?.(details.value)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
setContext('polymorph:Tabs', {
  get api() {
    return api
  },
  get keepMounted() {
    return keepMounted
  },
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    revealInline(list, list?.querySelector('[data-state="active"]'), true)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [list]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect1)
onDestroy(() => release1?.())
const effect2 = () => {
  revealInline(list, list?.querySelector('[data-state="active"]'))
}
watchEffect(effect2, { watch: () => api.value, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Tabs',
    element: () => list,
    state: () => ({
      value: api.value ?? null,
      tabs: tabs.map((tab) => ({
        id: tab.value,
        label: tab.label,
        ...(tab.disabled === true ? { disabled: true } : {}),
      })),
    }),
    actions: {
      choose: { argument: 'id', run: (value) => value === api.value || api.setValue(value) },
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div {...attributes(api.getRootProps())} class={styles.root} data-member="tabs"
    ><div
      bind:this={list}
      {...attributes(api.getListProps())}
      class={styles.list}
      data-tabs-part="list"
      >{#each tabs as tab (tab.value)
        }<button
          {...attributes(api.getTriggerProps({ value: tab.value, disabled: tab.disabled }))}
          class={styles.trigger}
          data-tabs-part="tab"
          data-state={api.value === tab.value ? 'active' : 'inactive'}
          data-disabled={tab.disabled ? '' : undefined}
          >{#if tab.icon !== undefined
            }<span class={styles.glyph}><Icon name={tab.icon} size="sm" /></span
          >{/if
          }<span>{tab.label}</span
          >{#if tab.count !== undefined
            }<span class={styles.count}
              ><Badge tone={api.value === tab.value ? 'accent' : 'neutral'}
                >{String(tab.count)
              }</Badge
            ></span
          >{/if
        }</button
      >{/each
      }<div
        {...attributes(api.getIndicatorProps())}
        class={[styles.indicator, styles.slide]}
        style:inline-size={orientation === 'vertical' ? undefined : Object(api.getIndicatorProps().style)['--width']}
        style:block-size={orientation === 'vertical' ? Object(api.getIndicatorProps().style)['--height'] : undefined}
      ></div
    ></div
    >{@render children?.()
  }</div
>{/if
}{@render joined.end?.()}
